### Configuration

## 📖 DESCRIPTION / OVERVIEW
Overview of the specified AfterLink communication module.

## 💻 CODE IMPLEMENTATION & BOILERPLATE

```javascript
import { Server } from '@afterlink/server';

const server = new Server({
  port: 4000,
  health: {
    enabled: true,
    // Optional: separate HTTP port (default: same port, protocol detection)
    port: 4002,
    // Optional: bearer token for authentication
    token: 'my-secret-token',
    // Optional: thresholds for degraded/unhealthy status
    thresholds: {
      maxConnections: 1000,    // Above this → degraded
      maxErrorRate: 10,        // Error rate % above this → degraded
      maxLatency: 5000,        // Avg latency (ms) above this → degraded
    },
  },
});

await server.listen();
```

### Same-Port Mode (default)

## 📖 DESCRIPTION / OVERVIEW
The health endpoint shares the main TCP port. Protocol detection on the TCP stream distinguishes HTTP `GET` requests from AfterLink HELLO frames.

## 💻 CODE IMPLEMENTATION & BOILERPLATE

```javascript
const server = new Server({
  port: 4000,
  health: { enabled: true },
});
// Health available at http://localhost:4000/__health
```

### Separate Port Mode

## 📖 DESCRIPTION / OVERVIEW
A dedicated HTTP server runs on a separate port.

## 💻 CODE IMPLEMENTATION & BOILERPLATE

```javascript
const server = new Server({
  port: 4000,
  health: { enabled: true, port: 4002 },
});
// Health available at http://localhost:4002/__health
// AfterLink protocol on port 4000
```

File: server.js
```javascript
const { Server } = require('@afterlink/server');

const server = new Server({
  port: 4000,
  health: {
    enabled: true,
  },
  browser: {
    enabled: true,
    port: 4001,
    path: '/ws',
    cors: {
      origins: ['*'],
    },
  },
});

server.on('ping', async (req, res) => {
  res.send({ pong: true, timestamp: Date.now() });
});

server.on('echo', async (req, res) => {
  res.send({ echoed: req.body });
});

server.on('chat.message', async (req, res) => {
  server.publish('chat.broadcast', {
    user: req.body.user || 'anonymous',
    text: req.body.text,
    timestamp: Date.now(),
  });
  res.send({ sent: true });
});

server.on('stats', async (req, res) => {
  res.send(server.getStats());
});

server.listen().then(() => {
  console.log('AfterLink server ready!');
  console.log('  TCP:      afterlink://localhost:4000');
  console.log('  WebSocket: ws://localhost:4001/ws');
  console.log('  Health:   http://localhost:4000/__health');
  console.log('  Open examples/browser-example/index.html in your browser');
});

server.handleProcessSignals();

```

