      message: `Route '${route}' timed out after ${timeoutMs}ms`,
      httpStatus: 408,
      details: { route, timeoutMs },
      ...options,
    });
    this.name = 'RouteTimeoutError';
  }
}

module.exports = {
  RouteError,
  RouteNotFoundError,
  RouteHandlerError,
  RouteTimeoutError,
