  0x05: 'STREAM_END', 0x06: 'ERROR', 0x07: 'PING', 0x08: 'PONG',
  0x09: 'BROADCAST', 0x0A: 'SUBSCRIBE', 0x0B: 'UNSUBSCRIBE', 0x0C: 'PUBLISH',
  0x0D: 'CLOSE', 0x0E: 'CLOSE_ACK', 0x0F: 'HELLO', 0x10: 'HELLO_ACK',
  0x11: 'SERVER_CLOSING',
};

