        } catch {
          process.stdout.write(`  Payload (raw hex): ${frame.payload.toString('hex')}\n`);
        }
        process.stdout.write('\n');

        // Exit after response or error
        if (frame.type === FrameTypes.RESPONSE || frame.type === FrameTypes.ERROR) {
          socket.destroy();
          process.exit(0);
        }
      }
    });

    socket.on('connect', () => {
      // Send HELLO
